const I=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${icons[n]||icons.arrow}" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const A={hero:'assets/hero.jpg',kumite:'assets/kumite.jpg',dojo:'assets/dojo.png'};
const logo=()=>`<a href="#/" class="logo" aria-label="GEKI Academy home"><span class="seal">極</span><span class="logotype">GEKI<small>ACADEMY</small></span></a>`;
const button=(label,href,kind='',icon='arrow')=>`<a class="btn ${kind}" href="#/${href}">${label}${icon?I(icon):''}</a>`;
const action=(label,act,kind='',icon='')=>`<button class="btn ${kind}" data-action="${act}">${label}${icon?I(icon):''}</button>`;
const badge=(label,kind='')=>`<span class="badge ${kind}">${label}</span>`;
const progress=(value=35,label='Course progress')=>`<div><div class="progress-label"><span>${label}</span><span>${value}%</span></div><div class="progress"><span style="width:${value}%"></span></div></div>`;
const checks=items=>`<ul class="check-list">${items.map(x=>`<li>${I('check')}<span>${x}</span></li>`).join('')}</ul>`;
const field=(label,placeholder='',type='text',value='')=>`<label>${label}<input type="${type}" placeholder="${placeholder}" ${value?`value="${value}"`:''} ${type==='email'?'autocomplete="email"':''}></label>`;
const head=(eye,title,sub='',extra='')=>`<header class="page-head"><div class="stack"><div class="eyebrow">${eye}</div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${extra}</header>`;
const lessonNames=['Welcome to Kihon','Stance, posture & balance','Seiken: the straight punch','Gedan Barai: lower block','Moving with purpose','Distance & timing','Taikyoku Sono I'];
const navItems=[['dashboard','home','Overview'],['my-learning','book','My Learning'],['library','grid','Course Library'],['quiz','quiz','Quizzes'],['membership','card','Membership'],['devices','devices','My Devices'],['notifications','bell','Notifications'],['settings','settings','Settings']];
const adminItems=[['admin','grid','Overview'],['admin/courses','book','Courses'],['admin/videos','film','Videos & Subtitles'],['admin/students','users','Students & Memberships'],['admin/quizzes','quiz','Quizzes'],['admin/audit','shield','Roles & Audit Logs']];
const routes=[['','Public landing'],['library','Course library'],['course','Course detail'],['preview','Free lesson preview'],['signin','Sign in'],['signup','Sign up'],['verify','Email verification'],['forgot','Forgot password'],['reset','Reset password'],['recovery','Account recovery'],['dashboard','Student dashboard'],['lesson','Video learning player'],['my-learning','My learning'],['quiz','Course quiz'],['quiz-results','Quiz passed'],['quiz-retry','Quiz retry'],['pricing','Membership & pricing'],['membership','Current membership'],['membership-expired','Expired membership'],['checkout','Checkout'],['payment-pending','Payment pending'],['payment-success','Payment successful'],['payment-failed','Payment failed'],['membership-activated','Membership activated'],['settings','Profile & settings'],['devices','Device management'],['notifications','Notifications'],['admin','Admin overview'],['admin/courses','Course management'],['admin/course-editor','Course editor'],['admin/videos','Video management'],['admin/subtitles','Subtitle editor'],['admin/students','Students & memberships'],['admin/student','Student details'],['admin/quizzes','Quiz editor'],['admin/audit','Super admin & audit'],['system','Design foundations'],['components','Component library'],['states','Feedback & edge states'],['motion','Motion direction']];
let current='',quizAnswer=-1,quizStep=0;
function publicNav(active=''){return `<nav class="public-nav shell">${logo()}<div class="nav-links"><a class="${active==='home'?'active':''}" href="#/">Home</a><a class="${active==='courses'?'active':''}" href="#/library">Courses</a><a href="#/#about">About GEKI</a><a class="${active==='membership'?'active':''}" href="#/pricing">Membership</a></div><div class="nav-actions"><button class="lang" data-action="language" aria-label="Change language">EN / <span class="myanmar">မြန်မာ</span>${I('down')}</button><a href="#/signin" class="sign-in">Sign in</a>${button('Get started','signup','small','up')}<button class="icon-btn menu-button" data-action="menu" aria-label="Open navigation">${I('menu')}</button></div></nav>`}
function footer(){return `<footer class="footer shell"><div class="footer-top">${logo()}<div class="footer-links"><a href="#/library">Explore courses</a><a href="#/pricing">Membership</a><a href="#/preview">Free lesson</a><a href="#/recovery">Support</a></div></div><div class="footer-word">GEKI ACADEMY</div><div class="footer-bottom"><span>© 2026 GEKI Academy. All rights reserved.</span><span>Traditional spirit. Modern science. Limitless growth.</span></div></footer>`}
function publicPage(body,active=''){return `${publicNav(active)}<main id="main" class="shell public-main">${body}</main>${footer()}`}
function sidebar(admin=false){return `<aside class="sidebar">${logo()}<div><div class="sidebar-label">${admin?'WORKSPACE':'YOUR ACADEMY'}</div><nav class="sidebar-nav">${(admin?adminItems:navItems).map(([href,icon,label])=>`<a href="#/${href}" class="${current===href?'active':''}">${I(icon)}<span>${label}</span></a>`).join('')}</nav></div><div class="sidebar-bottom">${admin?`<div class="panel"><div class="eyebrow">Workspace access</div><p>Admin · GEKI Academy</p><a class="text-link" href="#/dashboard">Student view ${I('up')}</a></div>`:`<div class="panel">${badge('Active member','green')}<p>Your next lesson is waiting.</p><a class="text-link" href="#/lesson">Continue learning ${I('arrow')}</a></div>`}<a class="profile-link" href="#/settings"><span class="avatar">${admin?'GA':'SL'}</span><span style="font-size:12px">${admin?'GEKI Admin':'Student Learner'}<small>${admin?'Content administrator':'Kyokushin member'}</small></span></a></div></aside>`}
function mobileBottom(admin=false){return `<nav class="mobile-bottom" aria-label="Main navigation">${(admin?[adminItems[0],adminItems[1],adminItems[2],adminItems[3]]:[navItems[0],navItems[1],navItems[2],navItems[4],navItems[7]]).map(([href,icon,label])=>`<a href="#/${href}" class="${current===href?'active':''}">${I(icon)}<span>${label.replace('Course Library','Library').replace('Overview','Home').replace('Students & Memberships','Students').replace('Videos & Subtitles','Videos')}</span></a>`).join('')}</nav>`}
function appPage(body,admin=false,crumb='Overview'){return `<div class="app-shell">${sidebar(admin)}<div class="app-main"><header class="app-topbar"><span class="mobile-logo">${logo()}</span><div class="breadcrumbs">${admin?'Administration':'My Academy'} ${I('chevron')} <span class="light">${crumb}</span></div><div class="row"><button class="lang" data-action="language">EN / <span class="myanmar">မြန်မာ</span></button><a class="icon-btn" href="#/notifications" aria-label="Notifications">${I('bell')}</a><a href="#/settings" class="avatar" aria-label="Account settings">${admin?'GA':'SL'}</a></div></header><main id="main" class="app-content ${admin?'admin-content':''}">${body}</main></div></div>${mobileBottom(admin)}`}
function courseCard(title='Geki Kihon Package',category='Kihon',image=A.hero,pro=0){return `<a class="course-card" href="#/course" data-category="${category}" data-title="${title.toLowerCase()}"><div class="card-image"><img src="${image}" alt="Karate technique study photography">${badge(category)}<span class="duration">${category==='Kihon'?'40 lessons · Approx. 10h':'Section of Geki Kihon Package'}</span></div><div class="card-body"><div class="eyebrow">KYOKUSHIN · FOUNDATIONS</div><h3>${title}</h3><p>${category==='Kata'?'Understand the movement. Find meaning in every form.':category==='Basic Kumite'?'Connect your fundamentals to distance, timing and control.':'Build a deeper understanding of the techniques you practice.'}</p>${pro?progress(pro):''}<div class="card-foot"><span>${pro?'Continue learning':'Included with membership'}</span>${I('up')}</div></div></a>`}
function videoBox(preview=false){return `<div class="video-box"><img src="${preview?A.hero:A.kumite}" alt="Karate instruction visual reference"><div class="player-top">${badge(preview?'FREE PREVIEW':'KIHON · LESSON 02',preview?'free':'')}<div class="watermark">GEKI ACADEMY<br>${preview?'PREVIEW':'MEMBER G-0024'}</div></div><button class="play-big" data-action="play" aria-label="Play lesson prototype">${I('play')}</button><div class="video-subtitle"><span>Keep your posture grounded. Let the movement begin from your stance.</span></div><div class="player-controls"><div class="timeline"><span></span></div><div class="control-row"><div class="row"><button data-action="play" aria-label="Play or pause">${I('play')}</button><button data-action="volume" aria-label="Mute or unmute">${I('volume')}</button><span>04:32 / 12:08</span></div><div class="row"><button data-action="subtitles" aria-label="Choose subtitles">${I('caption')}</button><button data-action="playback-settings" aria-label="Playback settings">${I('settings')}</button><button data-action="fullscreen" aria-label="Fullscreen player">${I('expand')}</button></div></div></div></div>`}
function lessonRows(preview=false,compact=false){return lessonNames.slice(0,compact?4:7).map((name,i)=>`<a href="#/${preview&&i>0?'pricing':'lesson'}" class="lesson-row ${!preview&&i===1?'current':''}">${compact?'':`<img src="${i%2?A.kumite:A.hero}" alt="">`}${I(preview&&i>0?'lock':i===0?'check':i===1?'play':'play')}<div class="row-copy"><span>${String(i+1).padStart(2,'0')}. ${name}</span><small>${i===0?'06:24':i===1?'12:08':'14:32'} ${!preview&&i===0?'· Completed':!preview&&i===1?'· In progress':''}</small></div>${preview&&i===0?badge('Free preview','free'):''}</a>`).join('')}
function landing(){return `<main id="main"><section class="hero"><img class="hero-photo" src="${A.hero}" alt="Karate practitioner performing a precise punch">${publicNav('home')}<div class="hero-mark" aria-hidden="true">極真</div><div class="hero-content shell full"><div class="eyebrow light reveal">THE KYOKUSHIN LEARNING EXPERIENCE</div><h1 class="reveal delay"><span>MASTER THE ART.</span><span class="outline">BUILD THE SPIRIT.</span></h1><p class="reveal delay">Authentic Kyokushin Karate education, guided by experience and powered by modern learning.</p><div class="row reveal delay">${button('Start learning','pricing','','up')}${button('Watch free lesson','preview','secondary','play')}</div></div><div class="hero-bottom shell full"><span>01 / THE JOURNEY BEGINS</span><span>ENGLISH INSTRUCTION · EN / MM SUBTITLES</span><a href="#/#about">SCROLL TO DISCOVER ↓</a></div></section><section class="section shell" id="about"><div class="intro scroll-reveal"><div class="eyebrow">DISCOVER GEKI</div><div class="stack"><h2>More than knowing the movement.<br><span>Understanding what makes it matter.</span></h2><p>Bring clarity to your dojo practice. Explore detailed visual explanations, revisit the fundamentals, and build knowledge you can carry onto the mat.</p></div></div><div class="pills-band scroll-reveal"><span>Spirit.</span><span>Science.</span><span>↗</span><span>Growth.</span></div></section><section class="section shell"><div class="section-head scroll-reveal"><div class="stack"><div class="eyebrow">YOUR FOUNDATION STARTS HERE</div><h2>One practice.<br>Many layers of understanding.</h2></div><a class="text-link" href="#/library">Explore your training ${I('up')}</a></div><div class="grid-3 scroll-reveal">${courseCard('The art of fundamentals','Kihon',A.hero)}${courseCard('Move with intention','Kihon Ido',A.dojo)}${courseCard('Control the distance','Basic Kumite',A.kumite)}</div></section><section class="shell section"><div class="feature scroll-reveal"><div class="feature-photo"><img src="${A.kumite}" alt="Kyokushin instructor demonstrating a kick in a dojo"><span class="vertical" aria-hidden="true">基本</span></div><div class="feature-content"><div class="eyebrow">THE SIGNATURE LEARNING JOURNEY</div><h2>Geki Kihon<br>Package.</h2><p>Learn the why behind the technique. A structured path from the foundations of Kihon to movement, Kumite and Kata.</p><div class="feature-steps"><span><b>01</b>Kihon fundamentals</span><span><b>02</b>Kihon Ido</span><span><b>03</b>Basic Kumite</span><span><b>04</b>Kata</span></div><div>${button('Discover the course','course','','up')}</div><small>40 videos planned · All lessons included with membership</small></div></div></section><section class="preview-band"><div class="shell preview-layout"><div class="stack"><div class="eyebrow">EXPERIENCE THE DIFFERENCE</div><h2>Your first lesson.<br>Our invitation.</h2><p>Watch the first Kihon lesson for free. No account. No commitment. Just a clearer understanding of your practice.</p><div>${button('Watch free lesson','preview','secondary','play')}</div></div>${videoBox(true)}</div></section><section class="section shell"><div class="section-head"><div class="stack"><div class="eyebrow">WHY GEKI</div><h2>Built for the way<br>you actually learn.</h2></div><p>Detailed instruction. A clear path. Room to learn at your own pace.</p></div><div class="method-grid scroll-reveal">${[['01','See the detail.','Clear visual explanations help you understand posture, movement and technique.'],['02','Return to the practice.','Resume where you left off. Revisit any lesson when you need another look.'],['03','Make it your own.','Reflect through course quizzes and bring your understanding back to the dojo.']].map(([n,t,p])=>`<div class="method-step"><span class="method-number">${n}</span><h3>${t}</h3><p>${p}</p></div>`).join('')}</div></section><section class="section shell"><div class="section-head"><div class="stack"><div class="eyebrow">THE LEARNING METHOD</div><h2>Watch. Understand.<br>Practice. Reflect.</h2></div><p>Explore freely, without artificial lesson locks. Your course keeps the structure; you set the pace.</p></div><div class="feature-steps"><span><b>01</b>Detailed visual instruction</span><span><b>02</b>English & Burmese subtitles</span><span><b>03</b>Saved learning progress</span><span><b>04</b>Knowledge checks with explanations</span></div></section><section class="section shell"><div class="eyebrow">GUIDED BY EXPERIENCE</div><div class="instructor-panel"><div class="portrait"><img src="${A.dojo}" alt="Karate instruction in a dojo; concept reference photography"></div><div class="stack"><h2>Meet your<br>GEKI instructors.</h2><p class="quote">The smallest detail can change the way you understand a technique.</p><p>Learn from invited GEKI instructors through focused, carefully structured explanations.</p><small>Instructor names, credentials and portraits to be supplied by GEKI.</small>${button('Explore the Kihon Package','course','ghost','up')}</div></div></section><section class="section shell"><div class="section-head"><div class="stack"><div class="eyebrow">ONE MEMBERSHIP. YOUR ENTIRE ACADEMY.</div><h2>Invest in<br>understanding.</h2></div><p>Monthly or annual access. Every available course, every lesson, and your progress in one place.</p></div><div class="grid-2">${pricingCard('Monthly',false,true)}${pricingCard('Annual',true,true)}</div></section><section class="closing"><div class="shell"><div class="eyebrow">YOUR NEXT CHAPTER</div><h2>Step onto the mat.<br>With a clearer mind.</h2>${button('Begin your journey','pricing','','up')}</div></section>${footer()}</main>`}
function library(){return publicPage(`${head('THE GEKI LIBRARY','Explore your training.','A deeper understanding starts with a closer look.') }<div class="banner"><img src="${A.hero}" alt="Karate fundamentals"><div class="stack"><div class="eyebrow">FEATURED · KYOKUSHIN FOUNDATIONS</div><h2>Geki Kihon Package.</h2><p>From your first stance to movement with purpose.</p><div>${button('Explore course','course','','up')}</div></div></div><div class="filters"><div class="search">${I('search')}<input id="library-search" aria-label="Search lessons and courses" placeholder="Search your training"></div><div class="chips">${['All','Kihon','Kihon Ido','Basic Kumite','Kata'].map((c,i)=>`<button class="chip ${!i?'active':''}" data-filter="${c}">${c}</button>`).join('')}</div></div><div class="grid-3" id="course-grid">${courseCard()}${courseCard('Kihon Ido: move with intention','Kihon Ido',A.dojo)}${courseCard('Basic Kumite: distance & timing','Basic Kumite',A.kumite)}${courseCard('Kata: meaning in movement','Kata',A.dojo)}</div><p id="no-results" class="panel" hidden>No matching lessons. Try a different title or category.</p>`,'courses')}
function course(){return publicPage(`<div class="eyebrow"><a href="#/library">COURSE LIBRARY</a> / GEKI KIHON PACKAGE</div><section class="course-hero"><img src="${A.hero}" alt="Kihon technique demonstration"><div class="stack"><div class="eyebrow">KYOKUSHIN · FOUNDATIONS</div><h1>Geki Kihon<br>Package.</h1><p>Understand the foundations. Connect every stance, block and strike to a purposeful practice.</p><div class="row"><span class="avatar">G</span><div class="stack sm"><span style="font-size:13px">GEKI Instruction Team</span><small>Invited Kyokushin instructors</small></div></div><div class="metadata"><span>Beginner friendly</span><span>40 planned lessons</span><span>Approx. 10 hours</span></div><div class="row wrap">${button('Start course','lesson','','play')}${badge('Included with membership')}</div><small>First lesson free · English instruction · EN / MM subtitles</small></div></section><div class="detail-columns"><div class="stack"><h2 style="font-size:30px">About this course</h2><p>Build a clearer foundation for your dojo training. Explore the essential mechanics of Kihon, then connect them to moving basics, Kumite and Kata. Watch in order or revisit the lesson you need.</p><h3>What you will learn</h3>${checks(['Recognize the relationship between stance, posture and balance.','Understand the purpose behind fundamental blocks and strikes.','Connect your basics to movement, distance and form.'])}<div class="row between"><h3>Your course curriculum</h3><small>All lessons open to members</small></div><div>${['01 — Kihon fundamentals','02 — Kihon Ido','03 — Basic Kumite','04 — Kata'].map((s,i)=>`<details class="lesson-section" ${i===0?'open':''}><summary><span>${s}</span><span>${i===0?'12':'8–10'} lessons ${I('down')}</span></summary>${i===0?lessonRows():`<a class="lesson-row" href="#/lesson">${I('play')}Explore ${s.slice(5)} lessons ${I('arrow')}</a>`}</details>`).join('')}</div><div class="panel row between"><div class="stack sm"><h3>Reflect on your learning</h3><p>Final quiz · 80% to pass · Unlimited retries</p></div><a href="#/quiz" class="icon-btn" aria-label="Open final quiz">${I('arrow')}</a></div></div><aside class="side-info"><div class="panel stack"><h3>A clear path.<br>Your own pace.</h3>${checks(['All lessons unlocked','English & Burmese subtitles','Save and resume your progress','Final course knowledge check'])}${button('Watch the free lesson','preview','secondary','play')}</div><div class="panel stack">${progress(35)}<p style="font-size:12px">Sample progress shown for a returning member.</p>${button('Continue learning','lesson','small')}</div><div class="panel stack"><div class="eyebrow">YOUR INSTRUCTORS</div><h3>GEKI Instruction Team</h3><p style="font-size:13px">Instructor biographies and verified credentials will appear here.</p></div></aside></div>`,'courses')}
function preview(){return publicPage(`<div class="preview-page"><div class="row between" style="margin-bottom:24px"><a class="text-link" href="#/course">${I('back')} Geki Kihon Package</a>${badge('NO ACCOUNT REQUIRED','free')}</div>${videoBox(true)}<div class="player-caption"><div class="eyebrow">YOUR FIRST KIHON LESSON</div><h1>Welcome to Kihon.</h1><div class="metadata"><span>GEKI Instruction Team</span><span>06:24</span><span>English · EN / MM subtitles</span></div><p style="margin-top:20px">Discover how careful observation can bring new clarity to the fundamentals you practice in your dojo.</p></div><div class="conversion"><div><div class="eyebrow">THE NEXT STEP IS YOURS</div><h3 style="margin-top:15px">Unlock the full GEKI experience.</h3><p style="font-size:13px">Every course. Every lesson. One membership.</p></div><div class="row">${button('Explore membership','pricing')}${button('Sign in','signin','ghost','')}</div></div><div class="block-head"><h3>Inside the full course</h3><small>Geki Kihon Package</small></div><div class="lesson-section">${lessonRows(true,true)}</div></div>`)}
function auth(kind){const info={signin:['WELCOME BACK','Return to your practice.','Sign in to continue your learning journey.'],signup:['YOUR JOURNEY STARTS HERE','Make room for growth.','Create your account. Explore your first lesson.'],verify:['ONE MORE STEP','Check your inbox.','Confirm your email before continuing to your account.'],forgot:['ACCOUNT RECOVERY','Find your way back.','We’ll send a password reset link to your email.'],reset:['RESET PASSWORD','A fresh start.','Choose a new password for your GEKI account.'],recovery:['HERE TO HELP','Recover your account.','Choose the route that matches how you signed in.']}[kind];let form='';if(kind==='signin'||kind==='signup'){form=`${action('Continue with Google','google','secondary full')}<div class="divider">OR CONTINUE WITH EMAIL</div><form class="stack" data-form="${kind}">${kind==='signup'?`${field('Learner display name','Your name')}<div class="field"><span style="font-size:13px;color:var(--muted)">Who is this account for?</span><div class="account-type"><label><input type="radio" name="learner" checked value="adult"> Myself · 18+</label><label><input type="radio" name="learner" value="child"> My child · 12–17</label></div><small>For a child, use a parent or guardian’s email.</small></div>`:''}${field(kind==='signup'?'Account email':'Email address','you@example.com','email')}<label>Password<div class="password-wrap"><input type="password" required minlength="8" autocomplete="${kind==='signup'?'new-password':'current-password'}" placeholder="${kind==='signup'?'Create a strong password':'Enter your password'}"><button type="button" data-action="toggle-password" aria-label="Show password">${I('eye')}</button></div></label>${kind==='signin'?'<a href="#/forgot" style="font-size:12px;text-align:right;color:#ccc">Forgot password?</a>':`<small>By creating an account, you agree to GEKI’s terms and privacy policy. Final policies require review before launch.</small>`}<button class="btn full" type="submit">${kind==='signin'?'Sign in':'Create account'}${I('arrow')}</button></form><p style="text-align:center;font-size:12px">${kind==='signin'?`New to GEKI? <a class="light" href="#/signup">Create an account</a>`:`Already a member? <a class="light" href="#/signin">Sign in</a>`}</p>`}else if(kind==='verify'){form=`<div class="state-icon">${I('mail')}</div><p>We’ve prepared a verification message for your account email. Open the link, then return here.</p>${action('Resend verification email','resend','full')}${button('I’ve verified my email','dashboard','secondary full')}<small>Check spam folders, or return to sign in to correct your email.</small>${button('Back to sign in','signin','ghost','back')}`}else if(kind==='forgot'){form=`<form class="stack" data-form="forgot">${field('Email address','you@example.com','email')}<button type="submit" class="btn full">Send reset link ${I('arrow')}</button></form><small>For your privacy, we show the same confirmation whether or not an account exists.</small>${button('Back to sign in','signin','ghost','back')}`}else if(kind==='reset'){form=`<form class="stack" data-form="reset">${field('New password','At least 8 characters','password')}${field('Confirm new password','Repeat your new password','password')}<button class="btn full" type="submit">Save new password ${I('arrow')}</button></form><small>This screen represents the valid reset-link state. Expired links offer a new reset request.</small>${button('Request a new reset link','forgot','ghost','back')}`}else{form=`<div class="panel stack"><h4>I used email and password</h4><p style="font-size:12px">Request a reset link to your account email.</p>${button('Reset password','forgot','secondary','arrow')}</div><div class="panel stack"><h4>I used Google</h4><p style="font-size:12px">Return to sign in and choose the same Google account.</p>${button('Return to sign in','signin','secondary','arrow')}</div><div class="notice">Still unable to sign in? Contact GEKI support through your dojo. Support contact details will be supplied before launch.</div>`}return `<main class="auth" id="main"><section class="auth-art"><img src="${A.hero}" alt="Karate training photography">${logo()}<div class="stack"><div class="eyebrow light">TRADITIONAL SPIRIT. MODERN SCIENCE.</div><h2>Discipline.<br>In every detail.</h2><p>GEKI Academy · Kyokushin</p></div></section><section class="auth-form-area"><div class="auth-form reveal"><div class="eyebrow">${info[0]}</div><h1>${info[1]}</h1><p style="font-size:13px">${info[2]}</p>${form}</div><div class="auth-bottom"><a href="#/preview">Watch free lesson</a><span>EN / မြန်မာ</span></div></section></main>`}
function dashboard(){return appPage(`${head('YOUR ACADEMY','Your journey to mastery continues.','Pick up where you left off. Bring one more detail into focus.')}<div class="dashboard-grid"><div><div class="continue-card"><img src="${A.kumite}" alt="Kyokushin training"><div class="stack"><div class="eyebrow light">CONTINUE LEARNING · LESSON 02</div><h2>Stance, posture<br>& balance.</h2><p>Geki Kihon Package · Kihon fundamentals</p>${progress(38,'Lesson progress')}<div class="row">${button('Resume lesson','lesson','','play')}<small>04:32 / 12:08</small></div></div></div><div class="stats-inline"><div><b>14 <span class="muted" style="font-size:16px">/ 40</span></b><small>Lessons completed</small></div><div><b>35<span style="font-size:16px">%</span></b><small>Course progress</small></div><div><b>1</b><small>Course in progress</small></div></div><div class="block-head"><h3>Your next steps</h3><a class="text-link" href="#/my-learning">My learning ${I('arrow')}</a></div><div class="mini-list">${[['Seiken: the straight punch',A.hero,'Kihon fundamentals · 14:32'],['Moving with purpose',A.dojo,'Kihon Ido · Explore any time'],['Reflect on your learning',A.kumite,'Final quiz · Unlimited retries']].map(([t,img,s],i)=>`<a href="#/${i===2?'quiz':'lesson'}"><img src="${img}" alt=""><div class="stack sm" style="flex:1"><h4>${t}</h4><p>${s}</p></div>${I('arrow')}</a>`).join('')}</div></div><aside class="side-info"><div class="panel"><div class="eyebrow">YOUR COURSE</div><div class="ring"><strong>35%</strong><small>COMPLETE</small></div><h4>Geki Kihon Package</h4><p style="font-size:12px;margin:12px 0 16px">Small details. Steady progress.</p>${button('View course','course','secondary small full','')}</div><div class="panel stack">${badge('Active membership','green')}<h4>Your academy is open.</h4><p style="font-size:12px">All available courses and lessons are included.</p><a class="text-link" href="#/membership">Manage membership ${I('arrow')}</a></div></aside></div>`)}
function lesson(){return appPage(`<div class="learn-layout"><div><div class="row between" style="margin-bottom:18px"><a href="#/course" style="font-size:12px;color:var(--muted)">← Geki Kihon Package</a><small>02 / 40</small></div>${videoBox()}<div class="lesson-detail"><div class="eyebrow">KIHON FUNDAMENTALS · LESSON 02</div><h1>Stance, posture & balance.</h1><div class="metadata"><span>GEKI Instruction Team</span><span>12:08</span><span>EN / MM subtitles</span></div><p>Learn how your stance supports every technique. Observe the relationship between your base, your posture and the direction of movement.</p><div class="panel stack"><h4>Bring this into your practice</h4>${checks(['Observe how your weight is distributed.','Notice alignment before adding speed.','Practice within your ability and follow your dojo instructor’s guidance.'])}</div>${progress(35)}<div class="next-prev">${button('Previous lesson','lesson','secondary','back')}${button('Next lesson','lesson','','arrow')}</div></div></div><aside class="lesson-aside"><div class="aside-head"><div class="eyebrow">YOUR COURSE</div><h3>Geki Kihon Package</h3>${progress(35)}</div><details open><summary>Course lessons · All available ${I('down')}</summary><div class="lesson-group-label">01 — Kihon fundamentals</div>${lessonRows(false,true)}${['02 — Kihon Ido','03 — Basic Kumite','04 — Kata'].map(t=>`<details><summary>${t} ${I('down')}</summary><a class="lesson-row" href="#/lesson">${I('play')} Explore this section</a></details>`).join('')}<a href="#/quiz" class="lesson-row">${I('quiz')}<div class="row-copy"><span>Final course quiz</span><small>80% to pass · Unlimited retries</small></div>${I('chevron')}</a></details></aside></div>`,false,'Geki Kihon Package')}
function myLearning(){return appPage(`${head('MY LEARNING','A practice worth returning to.','Your progress stays with you. Continue at your own pace.')}<nav class="tabs"><button class="active" data-learning-tab="progress">In progress <span class="muted">(1)</span></button><button data-learning-tab="completed">Completed <span class="muted">(0)</span></button></nav><div id="learning-content"><div class="grid-2">${courseCard('Geki Kihon Package','Kihon',A.hero,35)}<div class="panel stack"><div class="eyebrow">WHERE YOU LEFT OFF</div><h2 style="font-size:30px">Stance, posture<br>& balance.</h2><p>Resume lesson 02 at 04:32.</p>${progress(35)}<div class="row between"><small>14 / 40 lessons completed</small>${badge('Quiz not attempted')}</div>${button('Resume course','lesson','','play')}<a class="text-link" href="#/quiz">Open final quiz ${I('arrow')}</a></div></div></div>`,false,'My Learning')}
function quiz(result=false,retry=false){if(result)return appPage(`${head('COURSE ASSESSMENT','A moment to reflect.','Geki Kihon Package')}<div class="quiz-wrap"><div class="panel quiz-results"><div class="eyebrow">${retry?'KEEP BUILDING YOUR UNDERSTANDING':'ASSESSMENT COMPLETE'}</div><div class="score">${retry?'60':'90'}<span style="font-size:35px">%</span></div>${badge(retry?'Try again':'Passed',retry?'amber':'green')}<h2 style="font-size:30px;margin:25px 0 15px">${retry?'Another look. A deeper understanding.':'Your understanding is taking shape.'}</h2><p>${retry?'Review the explanations and revisit any lesson. There’s no limit to how many times you can try.':'Review your answers and return to your practice with greater clarity.'}</p><div class="metadata" style="justify-content:center;margin:25px 0"><span>Passing threshold: 80%</span><span>Unlimited retries</span></div><div class="row wrap" style="justify-content:center">${button(retry?'Retry quiz':'Review answers',retry?'quiz':'quiz-results',retry?'':'secondary',retry?'refresh':'quiz')}${button('Back to learning','lesson',retry?'secondary':'','arrow')}</div></div><div class="block-head"><h3>Answer explanations</h3><small>Sample review</small></div><div class="panel stack"><div class="row between"><h4>01 · A stable foundation</h4>${badge('Correct','green')}</div><p style="font-size:13px">A balanced stance supports controlled movement. Speed comes after alignment and stability.</p><hr><div class="row between"><h4>02 · Practice with control</h4>${badge('Review','amber')}</div><p style="font-size:13px">Avoid forcing range of motion. Revisit the lesson and follow your instructor’s guidance.</p>${button('Revisit stance & balance','lesson','ghost','arrow')}</div></div>`,false,'Quiz results');return appPage(`${head('COURSE ASSESSMENT','Understand. Then apply.','Geki Kihon Package · Final quiz')}<div class="quiz-wrap"><div class="panel quiz-panel"><div class="row between"><span class="eyebrow">QUESTION <span id="question-number">${quizStep+1}</span> OF 10</span>${badge('80% TO PASS')}</div><div style="margin-top:20px">${progress((quizStep+1)*10,'Assessment progress')}</div><h2 id="question-text">${quizStep===0?'What should you establish before adding speed to a technique?':'What is the best way to build a clearer understanding of a movement?'}</h2><div class="answers">${(quizStep===0?['A stable stance and controlled alignment','Maximum power in every repetition','The longest possible range of motion','The fastest possible execution']:['Observe carefully and practice with control','Rush through every repetition','Ignore posture to increase speed','Avoid revisiting foundational lessons']).map((t,i)=>`<button class="answer ${quizAnswer===i?'selected':''}" data-answer="${i}" aria-pressed="${quizAnswer===i}"><span class="answer-letter">${String.fromCharCode(65+i)}</span><span>${t}</span></button>`).join('')}</div><div class="row between" style="margin-top:30px">${action('Previous','quiz-previous','secondary small','back')}${action(quizStep===9?'Submit quiz':'Next question',quizStep===9?'quiz-submit':'quiz-next','','arrow')}</div></div><p style="font-size:11px;text-align:center;margin-top:22px">No timer. Take your time. Review your answers before submitting.</p></div>`,false,'Final quiz')}
function pricingCard(name,annual=false,compact=false){return `<div class="price-card ${annual?'annual':''}"><div class="row between"><div class="eyebrow">${annual?'A LONGER COMMITMENT':'START YOUR PRACTICE'}</div>${annual?badge('ANNUAL ACCESS','red'):''}</div><h2>${name} membership</h2><div class="price-value">Price to be announced<small> / ${annual?'year':'month'}</small></div><p style="font-size:13px">${annual?'One year to return, reflect, and grow.':'Your entire academy, one month at a time.'}</p>${checks(['Full video library','All available Kyokushin courses','Saved progress & course quizzes','English and Burmese subtitles','Two registered devices · One active stream'])}${button(compact?'Explore membership':`Choose ${name.toLowerCase()}`,compact?'pricing':'checkout',annual?'':'secondary','arrow')}<small>${annual?'Annual access period.':'Monthly access period.'} Renewal method confirmed at checkout.</small></div>`}
function pricing(){return publicPage(`<div class="pricing-head"><div class="eyebrow">ONE ACADEMY. ONE MEMBERSHIP.</div><h1>Make understanding<br>part of your practice.</h1><p>Choose the time that suits your journey. Both memberships include the same complete learning access.</p></div><div class="price-grid">${pricingCard('Monthly')}${pricingCard('Annual',true)}</div><p style="font-size:11px;text-align:center">Pricing and payment methods are awaiting business approval. No automatic billing is implied.</p><section class="faq"><h3 style="margin-bottom:25px">A few things to know.</h3>${[['What’s included?','Every available GEKI course and library video, progress tracking, and final course quizzes.'],['Can I use my phone and laptop?','Yes. Register up to two browser/device installations and watch on one at a time.'],['What happens when access expires?','Your paid lessons and quizzes lock, while your progress and results stay saved for renewal.'],['Can my child learn with GEKI?','Learners aged 12–17 use a parent-managed account. Each membership covers one learner.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section>`,'membership')}
function membership(expired=false){return appPage(`${head('MEMBERSHIP','Your access to the academy.','One membership. Every available course.')}<div class="settings-grid"><div class="panel stack"><div class="row between"><h3>Monthly membership</h3>${badge(expired?'Expired':'Active',expired?'amber':'green')}</div><p>${expired?'Your progress is safe. Renew to continue your learning.':'Every available Kyokushin lesson is yours to explore.'}</p><hr><div class="order-line"><span>Start date</span><span>1 Nov 2026</span></div><div class="order-line"><span>${expired?'Expired on':'Access until'}</span><span>${expired?'30 Oct 2026':'30 Nov 2026'}</span></div><div class="order-line"><span>Renewal</span><span>Method to be confirmed</span></div><div class="notice">Membership duration and automatic recurring billing are separate. Your approved payment method will determine renewal behavior.</div>${button(expired?'Renew membership':'Explore renewal options','pricing','','arrow')}</div><div class="panel stack"><div class="eyebrow">YOUR LEARNING STAYS WITH YOU</div><h3>${expired?'Continue where you left off.':'Room to keep growing.'}</h3>${progress(35)}${checks(['Progress and quiz results saved','One learner profile','Two registered devices','One active video stream'])}${button('Manage devices','devices','secondary')}</div></div><div class="block-head"><h3>Payment history</h3><small>Illustrative records</small></div>${table(['Reference','Plan','Date','Amount','Status'],[['GEKI-EXAMPLE-01','Monthly','1 Nov 2026','Price pending',badge('Completed','green')]])}`,false,'Membership')}
function checkout(){return publicPage(`${head('MEMBERSHIP CHECKOUT','A clear next step.','Review your membership before you continue.')}<div class="checkout-grid"><div class="panel stack"><h2>Payment method</h2><p style="font-size:13px">Local payment options will appear here once approved.</p><div class="payment-placeholder">${I('card')}<h4>Payment provider to be confirmed</h4><p>This is a design placeholder. No payment details are collected and no purchase can be processed.</p></div><label>Membership duration<select id="checkout-plan"><option>Monthly membership</option><option>Annual membership</option></select></label><div class="notice">The final price, payment method and renewal terms must be shown before a real purchase.</div><button class="btn full" disabled>Confirm purchase ${I('lock')}</button><a class="text-link" href="#/payment-pending">Preview payment status screens ${I('arrow')}</a></div><aside class="panel stack"><div class="eyebrow">ORDER SUMMARY</div><h2>GEKI membership</h2><p>Full access to the Kyokushin academy.</p><hr><div class="order-line"><span>Plan</span><span id="order-plan">Monthly</span></div><div class="order-line"><span>Price</span><span>Awaiting approval</span></div><div class="order-line"><span>Currency</span><span>To be confirmed</span></div><hr><div class="order-line"><strong>Total</strong><strong>Not yet set</strong></div>${checks(['All available courses','EN / MM subtitles','Progress & quizzes'])}<small>One learner · Two registered devices · One active stream</small></aside></div>`)}
function paymentState(kind){const info={pending:['clock','Payment pending.','Your payment is being checked. Membership access will update after confirmation.','Check status','payment-success','amber'],success:['check','Payment received.','Your payment has been recorded. We’re preparing your membership access.','View membership activation','membership-activated','green'],failed:['refresh','Payment didn’t complete.','Your membership has not been activated. Review the payment status before trying again.','Return to checkout','checkout','amber'],activated:['check','Your academy is open.','Your membership is active. Start with the first lesson or pick up where you left off.','Start learning','dashboard','green']}[kind];return publicPage(`<div class="state-card panel"><div class="state-icon">${I(info[0])}</div><div class="eyebrow">${kind==='activated'?'MEMBERSHIP ACTIVATED':'PAYMENT STATUS'}</div><h1>${info[1]}</h1><p>${info[2]}</p>${badge(kind==='activated'?'ACTIVE ACCESS':kind.toUpperCase(),info[6])}<hr style="width:100%;margin:0"><div class="order-line"><span>Membership</span><span>Monthly · Example</span></div><div class="order-line"><span>Reference</span><span>GEKI-EXAMPLE-01</span></div>${button(info[3],info[4],'full')}${kind==='pending'?button('Back to my account','membership','ghost'):''}<small>Design state only. No real transaction has occurred.</small></div>`)}
function settings(){return appPage(`${head('ACCOUNT SETTINGS','Your space. Your preferences.','Manage your learner profile and account.')}<div class="settings-grid"><section class="panel stack"><div class="row"><span class="avatar large">SL</span><div class="stack sm"><h3>Learner profile</h3><small>One learner associated with this account</small></div></div><form class="stack" data-form="settings">${field('Learner display name','Name','text','Student Learner')}${field('Account / guardian email','you@example.com','email')}<label>Preferred language<select><option>English</option><option>မြန်မာ</option></select></label><label>Account type<select><option>Adult learner · 18+</option><option>Parent-managed learner · 12–17</option></select></label><button class="btn" type="submit">Save changes ${I('check')}</button></form></section><div class="stack"><section class="panel stack"><h3>Security</h3><p style="font-size:13px">Use account recovery to update your password securely.</p>${button('Reset password','forgot','secondary','shield')}${button('Manage registered devices','devices','ghost','devices')}</section><section class="panel stack"><h3>Notifications</h3><p style="font-size:13px">Essential account, payment and membership messages keep you informed.</p><div class="row between"><span style="font-size:12px">Essential email notifications</span>${badge('Required')}</div><small>Marketing and learning reminders are outside launch scope.</small></section><section class="panel stack"><h3>Membership</h3>${badge('Active','green')}${button('View membership','membership','secondary')}</section><button class="text-link" data-action="signout">Sign out ${I('logout')}</button></div></div>`,false,'Settings')}
function devices(){return appPage(`${head('DEVICE MANAGEMENT','Your practice, on your devices.','Register up to two devices. Watch on one at a time.')}<div class="settings-grid"><section class="panel stack"><div class="row between"><h3>Registered devices</h3>${badge('2 / 2 devices')}</div><div class="device-card">${I('monitor')}<div class="device-copy"><div class="row wrap"><h4>Chrome · Windows</h4>${badge('This device','green')}</div><p>Last active just now</p><small>Registered 1 Nov 2026</small></div></div><div class="device-card">${I('phone')}<div class="device-copy"><h4>Safari · iPhone</h4><p>Last active 2 hours ago</p><small>Registered 2 Nov 2026</small></div><button data-action="remove-device">Remove</button></div><div class="notice">2 replacements available in this 30-day window. Removing a device revokes its access. Browser data resets may require registering again.</div><small>Need help replacing a device? Contact your GEKI administrator.</small></section><section class="panel stack"><div class="eyebrow">ACTIVE PLAYBACK</div><h3>One focused stream.</h3><p style="font-size:13px">If a lesson is already playing elsewhere, you can move playback to your current device.</p><div class="device-card">${I('phone')}<div class="device-copy"><h4>Safari · iPhone</h4><p>Stance, posture & balance</p>${badge('Playing','green')}</div></div>${action('Transfer playback here','transfer','secondary','play')}<small>Transferring will end the other active stream.</small></section></div>`,false,'My Devices')}
function notifications(){return appPage(`${head('NOTIFICATIONS','The updates that matter.','Your account, membership and learning access.',action('Mark all read','read-all','secondary small','check'))}<div class="tabs"><button class="active" data-notification-filter="all">All notifications</button><button data-notification-filter="unread">Unread</button></div><div class="table-wrap" id="notification-list">${[['card','Your membership is active.','Your academy access is ready. Continue with the Geki Kihon Package.','Just now','membership',true],['devices','A new device was registered.','Safari on iPhone was added to your two registered devices.','2 hours ago','devices',true],['mail','Your email is verified.','Your account is ready. You can access your profile and membership.','1 day ago','settings',false],['clock','Membership expiry reminder','Your example membership ends on 30 November. Explore renewal options.','Example reminder','membership',false]].map(([icon,t,p,time,href,unread])=>`<a class="notification ${unread?'unread':''}" href="#/${href}"><div class="icon-wrap">${I(icon)}</div><div class="stack"><h3>${t}</h3><p>${p}</p><small>${time}</small></div></a>`).join('')}</div>`,false,'Notifications')}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table><div class="table-footer"><span>Showing ${rows.length} illustrative records</span><div class="pagination"><button aria-label="Previous page" disabled>‹</button><button class="active" aria-current="page">1</button><button aria-label="Next page" disabled>›</button></div></div></div>`}
function metric(label,value,sub,icon){return `<div class="metric"><div class="metric-label">${label}${I(icon)}</div><b>${value}</b><small>${sub}</small></div>`}
function adminOverview(){return appPage(`${head('ADMIN WORKSPACE','Keep the academy moving.','Manage learning access, content and the work that needs your attention.',button('Upload video','admin/videos','small','plus'))}<div class="utility-bar"><span>Illustrative dashboard data · Final metrics will come from production records.</span>${badge('3 ITEMS NEED REVIEW','amber')}</div><div class="grid-4">${metric('Total students','200','Illustrative launch audience','users')}${metric('Active memberships','186','14 expired memberships','card')}${metric('Published courses','1','Geki Kihon Package','book')}${metric('Published videos','36','4 in preparation','film')}</div><div class="admin-columns"><div class="panel stack"><div class="row between"><h3>Membership activity</h3><small>Illustrative · Last 6 weeks</small></div><div class="bar-chart">${[30,48,40,66,82,95].map((v,i)=>`<div style="height:${v}%"><small>W${i+1}</small></div>`).join('')}</div><small style="margin-top:15px">Visual sample only; no production activity is represented.</small></div><div class="panel stack"><div class="row between"><h3>Needs attention</h3>${badge('3','amber')}</div><a class="notification" href="#/admin/subtitles" style="padding:15px 0"><div class="stack"><h3>2 subtitle tracks to review</h3><p>English & Burmese · Kihon fundamentals</p></div>${I('chevron')}</a><a class="notification" href="#/admin/videos" style="padding:15px 0"><div class="stack"><h3>1 video processing</h3><p>Processing status available in media</p></div>${I('chevron')}</a><div class="notice">Payment integration is not configured.</div></div></div><div class="block-head"><h3>Recent payment activity</h3><a href="#/admin/students" class="text-link">Manage memberships ${I('arrow')}</a></div>${table(['Reference','Learner','Plan','Status'],[['GEKI-EXAMPLE-01','Learner 024','Monthly',badge('Completed','green')],['GEKI-EXAMPLE-02','Learner 025','Annual',badge('Pending','amber')],['GEKI-EXAMPLE-03','Learner 026','Monthly',badge('Failed','red')]])}`,true,'Overview')}
function adminCourses(){return appPage(`${head('CONTENT MANAGEMENT','Build a clear learning path.','Organize courses, sections and reusable video lessons.',button('Create course','admin/course-editor','small','plus'))}<div class="filters"><div class="search">${I('search')}<input placeholder="Search courses" aria-label="Search courses" data-table-search></div><div class="chips"><button class="chip active">All courses</button><button class="chip" data-action="filter-toast">Published</button><button class="chip" data-action="filter-toast">Drafts</button></div></div>${table(['Course','Status','Lessons','Instructor credit','Updated',''],[[`<a class="row" href="#/admin/course-editor"><img src="${A.hero}" alt=""><span>Geki Kihon Package<br><small>Kyokushin · Foundations</small></span></a>`,badge('Published','green'),'40','GEKI Instruction Team','Today',`<a href="#/admin/course-editor" aria-label="Edit course">${I('edit')}</a>`]])}<div class="panel stack" style="margin-top:25px"><h3>One video. Multiple learning contexts.</h3><p style="font-size:13px">Reuse media across your library and course lessons. Keep the source video and subtitle approvals in one place.</p>${button('Open course editor','admin/course-editor','ghost')}</div>`,true,'Courses')}
function courseEditor(){return appPage(`${head('COURSE EDITOR','Geki Kihon Package.','A structured journey through the foundations of Kyokushin.',`<div class="row">${action('Save draft','save-draft','secondary small')}${action('Publish course','publish','small','up')}</div>`)}<div class="editor-grid"><div class="stack"><div class="panel stack"><div class="row between"><h3>Course details</h3>${badge('Draft')}</div><div class="tabs"><button class="active" data-editor-language="en">English</button><button data-editor-language="mm">မြန်မာ</button></div>${field('Course title','','text','Geki Kihon Package')}<label>Description<textarea>Understand the foundations. Connect every stance, block and strike to a purposeful practice.</textarea></label><div class="form-grid">${field('Instructor credit','','text','GEKI Instruction Team')}<label>Difficulty<select><option>Beginner friendly</option><option>Intermediate</option></select></label></div></div><div class="row between"><h3>Sections & lessons</h3>${action('Add section','add-section','secondary small','plus')}</div><div id="editor-sections">${['Kihon fundamentals','Kihon Ido','Basic Kumite','Kata'].map((s,i)=>`<section class="editor-section" style="margin-bottom:16px"><header><span>${String(i+1).padStart(2,'0')} — ${s}</span><button data-action="section-options" aria-label="Section options">${I('dots')}</button></header>${(i===0?lessonNames.slice(0,3):[s+' introduction']).map((l,j)=>`<div class="editor-lesson" draggable="true">${I('grip')}<span style="flex:1">${l}</span>${i===0&&j===0?badge('Free preview','free'):badge('Ready','green')}<button data-action="move-lesson" aria-label="Move lesson down">${I('down')}</button></div>`).join('')}<a class="editor-lesson" href="#/admin/videos">${I('plus')} Add existing video</a></section>`).join('')}</div></div><aside class="side-info"><div class="panel stack"><h3>Publishing checks</h3>${checks(['Course details complete','Lesson order configured','Preview lesson selected'])}<div class="notice">Confirm every video is ready and both subtitle tracks are approved before publishing.</div>${action('Review & publish','publish','full')}</div><div class="panel stack"><h3>Course thumbnail</h3><img src="${A.hero}" style="height:160px;width:100%;filter:grayscale(1);border-radius:8px" alt="Course thumbnail concept">${action('Choose thumbnail','thumbnail','secondary small')}</div><div class="panel stack"><h3>Final quiz</h3><p style="font-size:12px">80% pass mark · Unlimited retries</p>${button('Edit quiz','admin/quizzes','secondary small')}</div></aside></div>`,true,'Course editor')}
function adminVideos(){return appPage(`${head('MEDIA LIBRARY','Every detail, ready to teach.','Upload protected video and prepare both subtitle tracks.',action('Upload video','upload','small','upload'))}<div class="panel stack"><div class="workflow">${['Draft','Processing','Subtitle review','Ready','Published'].map((s,i)=>`<span class="${i<2?'done':i===2?'current':''}"><i>${i<2?'✓':i+1}</i>${s}</span>`).join('')}</div><label class="upload-zone" style="cursor:pointer"><span>${I('upload')}</span><h3>Bring a lesson into the academy.</h3><p>Choose a source video to begin upload and processing.</p><input type="file" accept="video/*" id="video-upload" style="max-width:100%"><small>Prototype only. File selection stays on your device.</small></label><div id="upload-progress" hidden>${progress(42,'Preparing upload preview')}<small>Simulated upload state — no file is transmitted.</small></div></div><div class="filters"><div class="search">${I('search')}<input placeholder="Search video library" aria-label="Search videos" data-table-search></div><div class="chips"><button class="chip active">All media</button><button class="chip" data-action="filter-toast">Needs review</button></div></div>${table(['Video','Duration','Processing','Subtitles','DRM',''],lessonNames.slice(0,4).map((n,i)=>[`<a class="row" href="#/admin/subtitles"><img src="${i%2?A.kumite:A.hero}" alt=""><span>${n}</span></a>`,i===0?'06:24':'12:08',badge(['Published','Subtitle review','Processing','Ready'][i],i===0||i===3?'green':'amber'),i===0?'EN ✓ · MM ✓':i===1?'EN ✓ · MM review':'Awaiting processing',badge('Protected'),`<a href="#/admin/subtitles">${I('edit')}</a>`]))}`,true,'Videos & subtitles')}
function subtitles(){return appPage(`${head('SUBTITLE REVIEW','Make every explanation clear.','Stance, posture & balance · English source audio',action('Approve both tracks','approve-subtitles','small','check'))}<div class="editor-grid"><div class="stack">${videoBox()}<div class="panel stack"><div class="row between"><h3>Subtitle tracks</h3>${badge('Review required','amber')}</div><div class="tabs"><button class="active" data-subtitle-tab="en">English transcription</button><button data-subtitle-tab="mm">Burmese translation</button></div><div id="subtitle-lines">${['Keep your posture grounded.','Let the movement begin from your stance.','Observe your alignment before adding speed.'].map((t,i)=>`<div class="subtitle-row"><div class="stack sm"><input aria-label="Subtitle ${i+1} start time" value="00:${String(i*4+10).padStart(2,'0')}.000"><small>→ 00:${String(i*4+14).padStart(2,'0')}.000</small></div><textarea aria-label="Subtitle line ${i+1}">${t}</textarea></div>`).join('')}</div><div class="row wrap">${action('Save corrections','save-subtitles','secondary small')}${action('Retry generation','retry-subtitles','ghost small','refresh')}</div></div></div><aside class="side-info"><div class="panel stack"><div class="eyebrow">REVIEW CHECKLIST</div><h3>Clarity before publication.</h3>${checks(['Timing matches the spoken audio','Japanese technique names reviewed','English meaning preserved','Burmese reviewed by an editor'])}<small>Review content carefully before approving either language.</small></div><div class="panel stack"><h3>Track status</h3><div class="row between"><small>English</small>${badge('Reviewed','green')}</div><div class="row between"><small>Burmese</small>${badge('Needs review','amber')}</div>${action('Approve both tracks','approve-subtitles','full')}</div><div class="notice">Rejecting a track keeps the lesson unpublished. Retry generation without uploading the video again.</div></aside></div>`,true,'Subtitle editor')}
function students(){return appPage(`${head('STUDENT OPERATIONS','Support every learner.','Manage memberships, account status and registered devices.')}<div class="grid-3">${metric('Registered learners','200','Illustrative records','users')}${metric('Active memberships','186','Monthly and annual plans','card')}${metric('Expired memberships','14','Progress retained','clock')}</div><div class="filters"><div class="search">${I('search')}<input placeholder="Search learner or reference" aria-label="Search students" data-table-search></div><div class="chips"><button class="chip active">All students</button><button class="chip" data-action="filter-toast">Active</button><button class="chip" data-action="filter-toast">Expired</button></div></div>${table(['Learner','Account','Membership','Plan','Access until','Devices',''],[1,2,3,4,5].map((n,i)=>[`<a class="row" href="#/admin/student"><span class="avatar">L${n}</span><span>Learner ${String(n+23).padStart(3,'0')}<br><small>${i===1?'Parent-managed':'Adult learner'}</small></span></a>`,badge(i===4?'Suspended':'Active',i===4?'red':'green'),badge(i===3?'Expired':'Active',i===3?'amber':'green'),i%2?'Annual':'Monthly',i===3?'30 Oct 2026':'30 Nov 2026','2 / 2',`<a href="#/admin/student" aria-label="Open learner">${I('chevron')}</a>`]))}`,true,'Students & memberships')}
function studentDetail(){return appPage(`${head('LEARNER DETAILS','Learner 024.','Illustrative account record',button('Back to students','admin/students','secondary small','back'))}<div class="admin-student-detail"><section class="panel stack"><div class="row"><span class="avatar large">L24</span><div class="stack sm"><h3>Learner 024</h3>${badge('Active account','green')}</div></div><div class="order-line"><span>Account type</span><span>Parent-managed · 12–17</span></div><div class="order-line"><span>Guardian contact</span><span>Verified account email</span></div><div class="order-line"><span>Preferred language</span><span>Burmese</span></div><hr><h3>Membership</h3><div class="order-line"><span>Monthly plan</span>${badge('Active','green')}</div><div class="order-line"><span>Expiry</span><span>30 Nov 2026</span></div><div class="row wrap">${action('Grant access','grant-access','secondary small')}${action('Revoke access','revoke-access','danger small')}</div></section><div class="stack"><div class="panel stack"><h3>Learning progress</h3>${progress(35,'Geki Kihon Package')}<div class="order-line"><span>Lessons completed</span><span>14 / 40</span></div><div class="order-line"><span>Quiz</span><span>Not attempted</span></div></div><div class="panel stack"><h3>Account controls</h3><p style="font-size:12px">Administrative actions require a reason and are recorded in the audit history.</p>${action('Reset registered devices','reset-devices','secondary','devices')}${action('Suspend account','suspend','danger','shield')}</div></div></div><div class="block-head"><h3>Payment history</h3></div>${table(['Reference','Plan','Status','Date'],[['GEKI-EXAMPLE-01','Monthly',badge('Completed','green'),'1 Nov 2026']])}`,true,'Learner detail')}
function adminQuiz(){return appPage(`${head('ASSESSMENT EDITOR','Build understanding, question by question.','Geki Kihon Package · Final course quiz',action('Publish quiz','publish-quiz','small','up'))}<div class="editor-grid"><div class="stack"><div class="panel stack"><div class="row between"><h3>Question 01</h3>${badge('Multiple choice')}</div><label>Question<textarea>What should you establish before adding speed to a technique?</textarea></label><div class="field"><span style="font-size:12px;color:var(--muted)">Answer options · Select the correct answer</span>${['A stable stance and controlled alignment','Maximum power in every repetition','The longest possible range of motion','The fastest possible execution'].map((t,i)=>`<label class="answer ${!i?'selected':''}" style="flex-direction:row"><input type="radio" name="correct-answer" ${!i?'checked':''} style="min-height:0;accent-color:var(--red)"><input aria-label="Answer ${String.fromCharCode(65+i)}" value="${t}" style="flex:1;background:none;border:0;min-height:30px;padding:0;font-size:12px"></label>`).join('')}</div><label>Answer explanation<textarea>A stable stance supports controlled movement. Establish alignment before adding speed.</textarea></label><div class="row between">${action('Save question','save-question','secondary small')}${action('Move question down','move-question','ghost small','down')}</div></div>${action('Add question','add-question','secondary','plus')}</div><aside class="side-info"><div class="panel stack"><h3>Quiz settings</h3><div class="order-line"><span>Passing score</span><span>80%</span></div><div class="order-line"><span>Attempts</span><span>Unlimited</span></div><div class="order-line"><span>Timer</span><span>None</span></div>${button('Preview quiz','quiz','secondary')}${action('Publish quiz','publish-quiz','','up')}</div><div class="panel stack"><h3>Attempt summary</h3><p style="font-size:12px">No production attempts yet. Results will appear after publication.</p></div></aside></div>`,true,'Quiz management')}
function audit(){return appPage(`${head('SUPER ADMIN','Accountability, by design.','Manage administrator access and review important changes.',action('Assign admin role','assign-role','small','plus'))}<div class="panel stack"><div class="row between"><h3>Administrator permissions</h3>${badge('Super Admin','red')}</div><div class="permission-grid"><div>Content administration ${I('check')}</div><div>Membership operations ${I('check')}</div><div>Device overrides ${I('check')}</div><div>Role assignments ${I('shield')}</div></div><small>Role changes require explicit confirmation. Operational changes include a reason and an audit event.</small></div><div class="block-head"><h3>Audit history</h3><div class="search">${I('search')}<input placeholder="Search audit events" aria-label="Search audit history" data-table-search></div></div>${table(['Time','Actor','Action','Target','Reason'],[['Today · 10:42','GEKI Admin','Subtitle approved','Kihon lesson 02','Language review complete'],['Today · 09:18','GEKI Admin','Device override','Learner 024','Device replacement support'],['Yesterday · 15:20','Super Admin','Role assigned','Content Admin','Invited administrator'],['Yesterday · 13:14','GEKI Admin','Membership extended','Learner 025','Verified renewal'],['Yesterday · 11:05','GEKI Admin','Course published','Geki Kihon Package','Content review complete']])}`,true,'Roles & audit logs')}
function system(){return publicPage(`<section class="design-cover"><div class="eyebrow">GEKI ACADEMY · DESIGN DIRECTION 01</div><h1>Disciplined by nature.<br><span class="muted">Designed for growth.</span></h1><p>A premium web learning experience. Dark athletic energy meets Japanese editorial restraint. An editable design package and responsive motion prototype.</p><div class="row wrap" style="margin-top:30px">${button('Explore the homepage','','','up')}${button('Component library','components','secondary','grid')}${button('Motion direction','motion','secondary','play')}</div></section><section class="section"><div class="section-head"><div class="stack"><div class="eyebrow">01 / FOUNDATIONS</div><h2>Controlled intensity.</h2></div><p>Martial red signals action, selection and progress. Neutral surfaces carry the learning.</p></div><div class="swatches">${[['Obsidian','#0A0A0A'],['Charcoal','#151515'],['Elevated','#202020'],['Martial Red','#D71920'],['Deep Crimson','#991B1B'],['White','#FFFFFF'],['Warm Off-White','#F5F4F0'],['Muted Gray','#929292'],['Border Gray','#303030']].map(([n,c])=>`<div class="swatch"><div class="swatch-color" style="background:${c}"></div><div class="swatch-label"><span>${n}</span><span>${c}</span></div></div>`).join('')}</div></section><section class="section"><div class="eyebrow">02 / TYPOGRAPHY</div><h2 style="margin:20px 0 35px">Clarity at every scale.</h2>${[['Display / 96–54','MASTER THE ART.',64],['Heading / 48–32','A deeper understanding.',40],['Title / 24–21','Stance, posture & balance.',24],['Body / 15–14','Bring clarity to the techniques you practice.',15],['Metadata / 12–11','KIHON · 12:08 · EN / MM',12]].map(([l,t,s])=>`<div class="type-row"><small>${l}</small><span style="font-size:clamp(${Math.min(s,28)}px,4vw,${s}px);letter-spacing:-.04em">${t}</span></div>`).join('')}<div class="type-row"><small>Burmese / Noto Sans Myanmar</small><span class="myanmar" style="font-size:22px">သင်ယူမှုကို ဆက်လက်လုပ်ဆောင်ပါ</span></div><p class="design-annotation" style="margin-top:25px">Geist for English; Noto Sans Myanmar for Burmese; Noto Sans JP for limited Japanese marks. Burmese translations are design samples requiring native-language review.</p></section><section class="section"><div class="eyebrow">03 / LAYOUT & RESPONSIVENESS</div><div class="grid-4" style="margin-top:30px">${[['1440','Desktop','12-column public layout; full learning sidebar.'],['1280','Laptop','Reduced gutters; same information hierarchy.'],['768','Tablet','Compact rail; stacked player and lesson list.'],['390','Mobile web','Single column; bottom navigation; collapsible lessons.']].map(([w,t,d])=>`<div class="panel stack"><h2>${w}</h2><h4>${t}</h4><p style="font-size:12px">${d}</p></div>`).join('')}</div><p class="design-annotation" style="margin-top:25px">Spacing scale: 4 / 8 / 12 / 16 / 24 / 32 / 48 / 64 / 96. Control radius: 6–9px. Cards: 12–18px. Touch targets: at least 44px. Reserve motion for hierarchy and feedback.</p></section><section class="section"><div class="section-head"><h2>The complete experience.</h2><small>40 screens and state routes</small></div><div class="screen-index">${routes.map(([r,t],i)=>`<a href="#/${r}"><span>${String(i+1).padStart(2,'0')} / ${t}</span>${I('up')}</a>`).join('')}</div></section><section class="section"><h3>Asset & implementation notes</h3><p style="margin-top:20px">Photography is for concept review and does not depict verified GEKI instructors. GEKI-owned, correctly licensed Kyokushin photographs and instructor details must replace reference assets before publication. This prototype does not process payments, authenticate users, implement DRM, or provide production account security.</p></section>`)}
function components(){return publicPage(`${head('SHARED DESIGN SYSTEM','A consistent language.','Reusable patterns for public, learning and administrative experiences.')}<div class="spec-grid"><section class="component-box"><h3>Buttons · states</h3><div class="component-states">${[['Default',''],['Hover','force-hover'],['Focus','force-focus']].map(([s,c])=>`<div class="sample"><small>${s}</small><button class="btn ${c}">Start learning ${I('arrow')}</button></div>`).join('')}<div class="sample"><small>Disabled</small><button class="btn" disabled>Continue ${I('arrow')}</button></div><div class="sample"><small>Loading</small><button class="btn" aria-busy="true">${I('refresh')} Loading</button></div></div><div class="row wrap">${button('Secondary','system','secondary')}${action('Destructive','demo-destructive','danger')}${button('Text link','system','ghost')}</div></section><section class="component-box"><h3>Fields · validation</h3>${field('Email address','you@example.com','email')}<label>Focused field<input class="force-focus" value="Learner profile"></label><label>Password<input style="border-color:#d71920" type="password" value="short"><span class="field-error">Use at least 8 characters.</span></label><label>Disabled field<input disabled value="Managed by account provider"></label></section><section class="component-box"><h3>Status & selection</h3><div class="row wrap">${badge('Active','green')}${badge('Pending','amber')}${badge('Expired','red')}${badge('Draft')}${badge('Free preview','free')}</div><div class="chips"><button class="chip active">All training</button><button class="chip">Kihon</button><button class="chip">Kata</button></div><nav class="tabs"><button class="active">In progress</button><button>Completed</button></nav><button class="answer selected"><span class="answer-letter">A</span>A stable stance and controlled alignment</button></section><section class="component-box"><h3>Progress & feedback</h3>${progress(35)}<div class="row"><div class="ring"><strong>35%</strong><small>COMPLETE</small></div><div class="stack">${badge('Saved','green')}<small>Progress saved automatically</small></div></div><div class="notice">Your membership expires soon. Progress will remain saved.</div></section><section class="component-box"><h3>Course card</h3>${courseCard('Geki Kihon Package','Kihon',A.hero,35)}</section><section class="component-box"><h3>Lesson, device & notification</h3><div class="lesson-section">${lessonRows(false,true)}</div><div class="device-card">${I('monitor')}<div class="device-copy"><h4>Chrome · Windows</h4><small>Current device</small></div>${badge('Active','green')}</div><div class="notification unread"><span class="icon-wrap">${I('bell')}</span><div class="stack"><h3>Your membership is active.</h3><p>Continue your learning.</p><small>Just now</small></div></div></section><section class="component-box"><h3>Overlays & menus</h3><div class="row wrap">${action('Confirmation dialog','remove-device','secondary')}${action('Playback settings','playback-settings','secondary')}${action('Language menu','language','secondary')}</div><div class="row wrap">${action('Toast notification','demo-toast')}${action('Student details drawer','student-drawer','secondary')}</div><small>Use these controls to inspect animated overlay states.</small></section><section class="component-box"><h3>Loading & empty</h3><div class="skeleton large"></div><div class="skeleton" style="width:70%"></div><div class="skeleton" style="width:50%"></div><div class="empty"><h3>Your learning starts here.</h3><p>Explore your first lesson.</p>${button('Browse courses','library','small')}</div></section></div><section class="section"><h3>Tables & pagination</h3><div style="margin-top:25px">${table(['Learner','Plan','Status','Action'],[['Learner 024','Monthly',badge('Active','green'),'<a href="#/admin/student">View details →</a>'],['Learner 025','Annual',badge('Pending','amber'),'<a href="#/admin/student">View details →</a>']])}</div></section>`)}
function states(){return publicPage(`${head('FEEDBACK & RECOVERY','Clear even when things go wrong.','Empty, loading, error and success states for essential journeys.')}<div class="state-grid">${[['No courses started','Explore the library and find your first lesson.','Browse courses','library','book'],['No search results','Try a shorter title or clear your category filters.','Clear filters','library','search'],['Membership expired','Your progress is saved. Renew to unlock paid lessons.','Explore renewal','pricing','lock'],['Connection interrupted','Playback pauses while the connection recovers. Your position stays saved.','Return to lesson','lesson','refresh'],['Playback unavailable','This browser may not support protected playback. Open Chrome or Safari.','View free preview','preview','monitor'],['Subtitle generation failed','Keep the draft private. Retry without uploading the video again.','Review media','admin/subtitles','caption'],['Reset link expired','Request another email to securely reset your password.','Request new link','forgot','mail'],['Device limit reached','Remove an existing registration to use this browser.','Manage devices','devices','devices'],['Payment failed','Access has not activated. Check the transaction status before retrying.','Review payment','payment-failed','card']].map(([t,p,b,h,ic])=>`<div class="empty">${I(ic)}<h3>${t}</h3><p>${p}</p>${button(b,h,'secondary small')}</div>`).join('')}</div><div class="spec-grid" style="margin-top:25px"><div class="component-box"><h3>Loading course content</h3><div class="skeleton large"></div><div class="skeleton" style="width:70%"></div><div class="skeleton" style="width:45%"></div><small>Loading status announced without exposing decorative skeletons.</small></div><div class="component-box"><h3>Changes saved</h3>${badge('Success','green')}<p>Your course draft is saved. It remains private until you publish it.</p><div class="form-message">The email or password could not be verified. Try again or reset your password.</div><small>Authentication errors avoid disclosing whether an account exists.</small></div></div>`)}
function motion(){return publicPage(`${head('MOTION & INTERACTION','Purpose in every movement.','Inspired by the attached Lumora reference; adapted to focused learning.')}<div class="spec-grid"><div class="stack"><div class="motion-demo" id="motion-demo"><div class="eyebrow">GEKI ACADEMY</div><div class="motion-line"><span><h2>MASTER THE ART.</h2></span></div><div class="motion-line"><span><h2 class="muted">BUILD THE SPIRIT.</h2></span></div><div class="row">${button('Start learning','pricing','small')}</div></div>${action('Replay entrance','replay-motion','secondary small','refresh')}</div><div class="panel stack"><h3>Hero choreography</h3><div class="motion-notes">Image settles from scale 1.08 → 1.02 over 1500ms.<br>Eyebrow enters with 24px rise and opacity.<br>Headline lines enter over 900ms with 120ms stagger.<br>CTA row follows with a restrained 160ms delay.<br>Easing: cubic-bezier(.22, 1, .36, 1).</div><p class="design-annotation">No artificial loading counter blocks learning. The reference’s reveal language is preserved without delaying access.</p></div><div class="panel stack"><h3>Cards & buttons</h3><p class="motion-notes">Course cards: translateY(-6px), border emphasis, image scale 1.045. Duration 350–700ms.<br>Buttons: translateY(-2px), 250ms.<br>Touch devices retain stable geometry.</p>${button('Try a button hover','library')}</div><div class="panel stack"><h3>Dialogs & navigation</h3><p class="motion-notes">Overlay entrance: opacity + translateY(16px) + scale(.98), 250ms.<br>Mobile navigation: clear selection states and responsive layout.<br>Screen changes: short 240–320ms content reveal.</p>${action('Open transfer dialog','transfer','secondary','play')}</div><div class="panel stack"><h3>Learning progress</h3>${progress(65,'Animated progress example')}<p class="motion-notes">Progress fills once on entry. No looping movement near lesson content or quiz answers.</p></div><div class="panel stack"><h3>Reduced motion</h3><p class="motion-notes">Honor prefers-reduced-motion. Remove translation, scale, stagger and shimmer. Preserve information, focus visibility and clear state changes.</p>${badge('SYSTEM PREFERENCE SUPPORTED','green')}</div></div><section class="section"><h3>Reference adaptation</h3><p style="margin-top:20px">Borrowed from the supplied Lumora description: oversized editorial headlines, asymmetrical content, cinematic imagery, word/line reveals, pill compositions, tactile hovers and considered overlays. Liquid cursor reveals are reserved for a future optional homepage experiment; they are not implemented in this prototype and never belong over lesson video.</p></section>`)}
function render(){current=decodeURIComponent(location.hash.replace(/^#\/?/,'').split('?')[0]);if(current==='#about'){current='';}let html='';if(!current)html=landing();else if(['signin','signup','verify','forgot','reset','recovery'].includes(current))html=auth(current);else{const pages={library,course,preview,dashboard,lesson,'my-learning':myLearning,quiz,'quiz-results':()=>quiz(true),'quiz-retry':()=>quiz(true,true),pricing,membership,'membership-expired':()=>membership(true),checkout,'payment-pending':()=>paymentState('pending'),'payment-success':()=>paymentState('success'),'payment-failed':()=>paymentState('failed'),'membership-activated':()=>paymentState('activated'),settings,devices,notifications,admin:adminOverview,'admin/courses':adminCourses,'admin/course-editor':courseEditor,'admin/videos':adminVideos,'admin/subtitles':subtitles,'admin/students':students,'admin/student':studentDetail,'admin/quizzes':adminQuiz,'admin/audit':audit,system,components,states,motion};html=(pages[current]||system)()}document.querySelector('#app').innerHTML=html;document.body.classList.toggle('public-page',!document.querySelector('.app-shell'));document.title=`${routes.find(([r])=>r===current)?.[1]||'GEKI Academy'} — GEKI`;window.scrollTo(0,0);document.querySelectorAll('.scroll-reveal').forEach(el=>observer.observe(el));document.querySelectorAll('form input:not([type=radio])').forEach(el=>el.required=true);if(location.hash.endsWith('#about'))document.querySelector('#about')?.scrollIntoView({behavior:'smooth'});}
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),4000)}
function modal(title,body,footer=''){const d=document.querySelector('#modal');d.innerHTML=`<header class="dialog-header"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${I('close')}</button></header><div class="dialog-content">${body}</div>${footer?`<footer class="dialog-footer">${footer}</footer>`:''}`;d.showModal()}
function navDialog(){const d=document.querySelector('#navigator');d.innerHTML=`<header class="dialog-header"><div class="stack sm"><h2 id="nav-title">GEKI design index</h2><small>Interactive design only · No real payments or account changes</small></div><button class="icon-btn" data-action="close-nav" aria-label="Close navigator">${I('close')}</button></header><div class="screen-index">${routes.map(([r,t],i)=>`<a href="#/${r}"><span>${String(i+1).padStart(2,'0')} / ${t}</span>${I('up')}</a>`).join('')}</div>`;d.showModal()}
const confirm=(title,body,label='Confirm',act='confirm-demo')=>modal(title,`<p>${body}</p>`,`${action('Cancel','close-modal','secondary')}${action(label,act,'danger')}`);
document.querySelector('#review-launch').addEventListener('click',navDialog);
document.addEventListener('click',e=>{const answer=e.target.closest('[data-answer]');if(answer){quizAnswer=Number(answer.dataset.answer);document.querySelectorAll('.answer[data-answer]').forEach(el=>{el.classList.toggle('selected',el===answer);el.setAttribute('aria-pressed',String(el===answer))});return}const filter=e.target.closest('[data-filter]');if(filter){document.querySelectorAll('[data-filter]').forEach(c=>c.classList.toggle('active',c===filter));filterCourses();return}const a=e.target.closest('a');if(a){document.querySelector('#navigator').close();if(a.hash===location.hash&&current==='quiz-results'){toast('Answer explanations are shown below your score.')}if(a.hash==='#/#about'){e.preventDefault();if(current){location.hash='#/';setTimeout(()=>document.querySelector('#about')?.scrollIntoView({behavior:'smooth'}),80)}else document.querySelector('#about')?.scrollIntoView({behavior:'smooth'});return}}const ltab=e.target.closest('[data-learning-tab]');if(ltab){document.querySelectorAll('[data-learning-tab]').forEach(t=>t.classList.toggle('active',t===ltab));document.querySelector('#learning-content').innerHTML=ltab.dataset.learningTab==='completed'?`<div class="empty">${I('book')}<h3>Your next milestone is ahead.</h3><p>Complete your lessons and pass the course quiz to see your completed course here.</p>${button('Continue learning','lesson')}</div>`:`<div class="grid-2">${courseCard('Geki Kihon Package','Kihon',A.hero,35)}</div>`;return}const nfilter=e.target.closest('[data-notification-filter]');if(nfilter){document.querySelectorAll('[data-notification-filter]').forEach(t=>t.classList.toggle('active',t===nfilter));document.querySelectorAll('.notification').forEach(t=>t.hidden=nfilter.dataset.notificationFilter==='unread'&&!t.classList.contains('unread'));return}const subtitle=e.target.closest('[data-subtitle-tab]');if(subtitle){const mm=subtitle.dataset.subtitleTab==='mm';document.querySelectorAll('[data-subtitle-tab]').forEach(t=>t.classList.toggle('active',t===subtitle));document.querySelectorAll('#subtitle-lines textarea').forEach((t,i)=>{t.value=mm?['ကိုယ်ဟန်အနေအထားကို တည်ငြိမ်စွာ ထိန်းထားပါ။','လှုပ်ရှားမှုကို ရပ်တည်ပုံမှ စတင်ပါ။','အရှိန်မမြှင့်မီ ကိုယ်ဟန်အနေအထားကို သတိပြုပါ။'][i]:['Keep your posture grounded.','Let the movement begin from your stance.','Observe your alignment before adding speed.'][i];t.classList.toggle('myanmar',mm)});return}const elang=e.target.closest('[data-editor-language]');if(elang){document.querySelectorAll('[data-editor-language]').forEach(t=>t.classList.toggle('active',t===elang));toast('Bilingual editing state selected. Final translations require review.');return}const target=e.target.closest('[data-action]');if(!target)return;const act=target.dataset.action;const actions={
'close-modal':()=>document.querySelector('#modal').close(),'close-nav':()=>document.querySelector('#navigator').close(),menu:()=>modal('Explore GEKI',`<div class="stack">${[['','Home'],['library','Courses'],['pricing','Membership'],['signin','Sign in']].map(([r,t])=>`<a class="text-link" href="#/${r}" onclick="document.querySelector('#modal').close()">${t}${I('arrow')}</a>`).join('')}</div>`),language:()=>modal('Choose your language',`<p>Interface language and video subtitles can be selected independently.</p><button class="answer selected" data-action="language-en">English ${I('check')}</button><button class="answer myanmar" data-action="language-mm">မြန်မာ</button><small>Burmese typography and representative copy are provided. A full interface translation requires editorial review.</small>`),'language-en':()=>{document.documentElement.lang='en';document.querySelector('#modal').close();toast('English selected.')},'language-mm':()=>{document.querySelector('#modal').close();toast('Burmese typography preview is available in Design foundations. Full translation pending review.')},google:()=>toast('Design prototype: Google sign-in will connect through Firebase during implementation.'),'toggle-password':()=>{const input=target.parentElement.querySelector('input');input.type=input.type==='password'?'text':'password';target.setAttribute('aria-label',input.type==='password'?'Show password':'Hide password')},resend:()=>toast('Prototype: verification resend confirmation.'),signout:()=>{location.hash='#/signin'},play:()=>{const box=target.closest('.video-box');const playing=box.dataset.playing==='true';box.dataset.playing=String(!playing);box.querySelectorAll('[data-action=play]').forEach(b=>b.innerHTML=I(playing?'play':'pause'));toast(playing?'Playback paused.':'Playback interaction preview. Production DRM video is not connected.')},volume:()=>toast('Volume control preview.'),fullscreen:()=>{const box=target.closest('.video-box');box.requestFullscreen?.().catch(()=>toast('Fullscreen is unavailable in this browser context.'))},subtitles:()=>modal('Video subtitles',`<button class="answer selected" data-action="subtitle-en">English ${I('check')}</button><button class="answer myanmar" data-action="subtitle-mm">မြန်မာ</button><button class="answer" data-action="subtitle-off">Off</button>`),'subtitle-en':()=>selectSub('en'),'subtitle-mm':()=>selectSub('mm'),'subtitle-off':()=>selectSub('off'),'playback-settings':()=>modal('Playback settings',`<label>Quality<select><option>Auto · adapts to your connection</option><option>720p</option><option>480p</option><option>360p · lower data use</option></select></label><label>Playback speed<select><option>1× · Normal</option><option>0.75×</option><option>1.25×</option><option>1.5×</option></select></label><small>Actual controls depend on the selected DRM player’s supported capabilities.</small>`,action('Done','close-modal')),'remove-device':()=>confirm('Remove this device?','Safari on iPhone will lose access. This uses one of your two replacements in a rolling 30-day window.','Remove device','confirm-remove'),'confirm-remove':()=>{document.querySelector('#modal').close();document.querySelectorAll('.device-card').forEach(d=>{if(d.textContent.includes('Safari')&&d.querySelector('[data-action=remove-device]'))d.remove()});toast('Device removed in this design preview.')},transfer:()=>confirm('Move playback here?','Your active lesson on Safari will stop. You can then continue on this device.','Transfer playback','confirm-transfer'),'confirm-transfer':()=>{document.querySelector('#modal').close();toast('Playback transferred in this preview.')},'read-all':()=>{document.querySelectorAll('.notification.unread').forEach(n=>n.classList.remove('unread'));toast('All notifications marked as read.')},'quiz-next':()=>{if(quizAnswer<0)return toast('Choose an answer before continuing.');quizStep=Math.min(9,quizStep+1);quizAnswer=-1;render()},'quiz-previous':()=>{quizStep=Math.max(0,quizStep-1);quizAnswer=-1;render()},'quiz-submit':()=>{if(quizAnswer<0)return toast('Choose an answer before submitting.');location.hash='#/quiz-results'},'save-draft':()=>toast('Course draft saved in this preview.'),publish:()=>confirm('Publish this course?','Check video readiness, both approved subtitle tracks, quiz content and the free preview before making this course visible.','Publish course'),'approve-subtitles':()=>confirm('Approve both subtitle tracks?','Confirm that English timing, Burmese meaning and Japanese technique names have been reviewed.','Approve tracks'),'retry-subtitles':()=>toast('Subtitle retry queued in this preview; existing draft remains private.'),'save-subtitles':()=>toast('Subtitle corrections saved in this preview.'),'grant-access':()=>modal('Grant learner access',`${field('Reason','Why is access being granted?')}<label>Access ends<input type="date"></label><small>This action must be audited in production.</small>`,action('Confirm access grant','confirm-demo')),'revoke-access':()=>adminConfirm('Revoke membership access?','Paid playback will be denied. Learning progress remains saved.'),'reset-devices':()=>adminConfirm('Reset registered devices?','The learner must register their browsers again. This override is recorded.'),suspend:()=>adminConfirm('Suspend this account?','Sign-in access to protected content will be denied until an admin restores the account.'),'assign-role':()=>modal('Assign administrator role',`${field('Account email','admin@example.com','email')}<label>Role<select><option>Admin</option><option>Super Admin</option></select></label>${field('Reason','Reason for this assignment')}<div class="notice">Role assignments require a Super Admin and an audit record.</div>`,action('Confirm role assignment','confirm-demo','danger')),'publish-quiz':()=>confirm('Publish this quiz?','Confirm correct answers, explanations and the 80% pass threshold. Existing attempts must retain their recorded results.','Publish quiz'),'confirm-demo':()=>{document.querySelector('#modal').close();toast('Confirmed in prototype only. No production data was changed.')},'add-section':()=>{const div=document.createElement('section');div.className='editor-section';div.innerHTML='<header>05 — New section</header><div class="editor-lesson">Add an existing video to this section.</div>';document.querySelector('#editor-sections').append(div)},'move-lesson':()=>{const row=target.closest('.editor-lesson');if(row.nextElementSibling?.classList.contains('editor-lesson'))row.parentElement.insertBefore(row.nextElementSibling,row)},'section-options':()=>modal('Section options',`${field('Section title','Section name')}${action('Save section','confirm-demo')}`),'thumbnail':()=>toast('Thumbnail selection will use the approved media provider.'),upload:()=>document.querySelector('#video-upload')?.click(),'filter-toast':()=>toast('Filter state preview. This sample contains a limited illustrative dataset.'),'add-question':()=>toast('New question added to the draft in this preview.'),'save-question':()=>toast('Question saved in this preview.'),'move-question':()=>toast('Question ordering preview.'),'demo-toast':()=>toast('Changes saved. Your course remains a draft.'),'demo-destructive':()=>confirm('Confirm this action?','Destructive actions explain their effect before confirmation.'),'student-drawer':()=>{modal('Learner 024',`<div class="row"><span class="avatar large">L24</span><div class="stack sm"><h3>Learner profile</h3>${badge('Active membership','green')}</div></div>${progress(35)}${button('Open full learner details','admin/student')}`);document.querySelector('#modal a').onclick=()=>document.querySelector('#modal').close()},'replay-motion':()=>{const el=document.querySelector('#motion-demo');const clone=el.cloneNode(true);el.replaceWith(clone)}
};actions[act]?.()});
function adminConfirm(title,copy){modal(title,`<p>${copy}</p>${field('Required reason','Describe why this action is needed')}<small>Preview only. Production requires server authorization and audit history.</small>`,`${action('Cancel','close-modal','secondary')}${action('Confirm','confirm-demo','danger')}`)}
function selectSub(lang){document.querySelectorAll('.video-subtitle').forEach(el=>{el.hidden=lang==='off';el.classList.toggle('myanmar',lang==='mm');el.innerHTML=`<span>${lang==='mm'?'ကိုယ်ဟန်အနေအထားကို တည်ငြိမ်စွာ ထိန်းထားပါ။':'Keep your posture grounded. Let the movement begin from your stance.'}</span>`});document.querySelector('#modal').close()}
function filterCourses(){const q=document.querySelector('#library-search')?.value.toLowerCase()||'';const filter=document.querySelector('[data-filter].active')?.dataset.filter||'All';let count=0;document.querySelectorAll('#course-grid .course-card').forEach(c=>{c.hidden=!(c.dataset.title.includes(q)&&(filter==='All'||c.dataset.category===filter));if(!c.hidden)count++});document.querySelector('#no-results').hidden=!!count}
document.addEventListener('input',e=>{if(e.target.id==='library-search')filterCourses();if(e.target.matches('[data-table-search]')){const q=e.target.value.toLowerCase();document.querySelectorAll('tbody tr').forEach(tr=>tr.hidden=!tr.textContent.toLowerCase().includes(q))}});
document.addEventListener('change',e=>{if(e.target.id==='video-upload'){document.querySelector('#upload-progress').hidden=false;toast('Local file selected. No video has been uploaded.')}if(e.target.id==='checkout-plan')document.querySelector('#order-plan').textContent=e.target.value.startsWith('Annual')?'Annual':'Monthly'});
document.addEventListener('submit',e=>{const type=e.target.dataset.form;if(!type)return;e.preventDefault();if(type==='signin')location.hash='#/dashboard';if(type==='signup')location.hash='#/verify';if(type==='forgot')modal('Check your inbox.',`<p>If an account matches that email, a password reset link will be sent. This is a prototype confirmation.</p>`,button('Back to sign in','signin'));if(type==='reset'){const p=[...e.target.querySelectorAll('input')].map(i=>i.value);if(p[0]!==p[1])return toast('The passwords do not match.');toast('Password reset preview complete.');location.hash='#/signin'}if(type==='settings')toast('Profile changes saved in this preview.')});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d)d.close()}));
window.addEventListener('hashchange',()=>{document.querySelectorAll('dialog[open]').forEach(d=>d.close());render()});
window.GEKI_DESIGN={routes,render};render();
